import{readFile,writeFile}from'node:fs/promises';import{createHash}from'node:crypto';import{dirname,join}from'node:path';import{fileURLToPath}from'node:url';const d=dirname(fileURLToPath(import.meta.url)),i=JSON.parse(await readFile(join(d,'bundle-input.v1.json'),'utf8')),e=await readFile(join(d,'src','executor.source.mjs'),'utf8'),t=await readFile(join(d,'src','bundle.template.js'),'utf8'),o=t.replace('/*__SPEC__*/',JSON.stringify(i.spec)).replace('/*__MANIFEST__*/',JSON.stringify(i.manifest)).replace('/*__ASSETS__*/',JSON.stringify(i.assets)).replace('/*__EXECUTOR__*/',e.replace(/^import[^\n]+\n/,'').replace('export async function run','async function run').replace('export const TEST_ONLY','const TEST_ONLY')),p=join(d,'dist','penpot-plugin.bundle.js');if(process.argv.includes('--check')){if(await readFile(p,'utf8')!==o)throw Error('DETERMINISTIC_REGENERATION_MISMATCH')}else await writeFile(p,o,'utf8');console.log(JSON.stringify({bytes:Buffer.byteLength(o),sha256:createHash('sha256').update(o).digest('hex')}));